#!/usr/bin/env bash
# Runs BOTH test scenarios end to end by calling the scripts directly with `python3` (no Docker wrapper, no `python` alias).
# The model-written judgements (results parts, per_person, classification, v2 model, changelog) come from the committed
# samples in tests/run and tests/run2; everything else is regenerated by the scripts. Usage: [ENGINE=pdftotext|pypdf] run_deterministic.sh OUTDIR
set -euo pipefail
REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="$(mkdir -p "$1" && cd "$1" && pwd)"
S1="$REPO/tests/run"; S2="$REPO/tests/run2"; F="$REPO/tests/fixtures"; P="$F/process"
cd "$OUT"; ln -sfn "$F" fixtures; mkdir -p s1 s2
sc() { local s="$1"; shift; python3 "$REPO/scripts/$s" "$@"; }
EA=(); [ -n "${ENGINE:-}" ] && EA=(--engine "$ENGINE")   # optional primary PDF engine

echo "### scenario 1: rule check"
sc extract.py "$F/target_srs.pdf" "$F/rules.pdf" "$F/review.docx" --docx-source "$F/review.docx" "${EA[@]}" -o s1/ex
python3 "$REPO/tests/build_rules.py" s1/ex/rules.txt s1/rules.json rules.pdf
sc id_index.py s1/ex/target_srs.txt -o s1/id_index.json
sc xref_check.py s1/ex/target_srs.txt --numbers --also-numbers s1/ex/rules.txt -o s1/xref_report.md >/dev/null
sc matrix.py skeleton s1/rules.json s1/ex/target_srs.txt -o s1/matrix
cp "$S1/part_01.json" "$S1/part_02.json" "$S1/internal.md" "$S1/per_person.md" s1/
sc matrix.py set-bulk s1/results.json s1/part_01.json >/dev/null
sc matrix.py set-bulk s1/results.json s1/part_02.json
sc matrix.py status s1/rules.json s1/results.json
sc matrix.py coverage s1/rules.json s1/results.json -o s1/coverage.md
{ printf '# Rule Check Report\n**Target:** target_srs.pdf  **Reference:** rules.pdf  **Review:** review.docx (2 people, 8 comments, 2 tracked changes)\n**Classification:** test scenario, no question to the user needed. No immutable document.\n\n'; cat s1/coverage.md; echo; cat s1/internal.md; } > s1/report.md
sc matrix.py verify s1/rules.json s1/report.md
python3 "$REPO/tests/score.py" s1

echo; echo "### scenario 1b: DOCX target, tables, environment (new)"
mkdir -p s1docx
sc env_check.py --json s1/env.json | sed -n 1,9p
sc extract.py "$F/target_srs.docx" -o s1docx/ex
sc xref_check.py s1docx/ex/target_srs.txt -o s1docx/xref_report.md | sed -n 3,6p
sc docx_to_pdf.py "$F/target_srs.docx" -o s1docx/pdf --timeout 60
python3 "$REPO/tests/check_converted_pdf.py" s1docx/pdf || echo "check_converted_pdf: FAIL"
sc docx_to_pdf.py "$F/target_srs.docx" -o s1docx/pdf_timeout --timeout 0.01
if [ -s s1docx/pdf/target_srs.pdf ]; then
  sc extract.py s1docx/pdf/target_srs.pdf -o s1docx/ex_lo | grep -E "warnings|WARNING|->"
  sc extract.py s1docx/pdf/target_srs.pdf --engine pypdf -o s1docx/ex_lo_pypdf | grep -E "warnings|WARNING|->"
fi
sc extract.py "$F/target_srs.pdf" --tables -o s1/ex_tables | grep -E "WARNING|->"
python3 "$REPO/tests/check_tables.py" s1/ex_tables
# hardest non-reportlab PDF: two columns, justified text, ligatures, bordered table (needs LibreOffice to build the PDF)
mkdir -p s1docx/stress
sc docx_to_pdf.py "$F/stress.fodt" -o s1docx/stress/pdf --timeout 60
if [ -s s1docx/stress/pdf/stress.pdf ]; then
  for eng in pdftotext pypdf; do for mode in layout reading; do
    ro=(); [ "$mode" = reading ] && ro=(--reading-order)
    sc extract.py s1docx/stress/pdf/stress.pdf --engine $eng "${ro[@]}" --tables -o s1docx/stress/ex_${eng}_$mode | grep -E "warnings"
  done; done
fi
VIS=(); [ -f s1docx/pdf/visual_status.json ] && VIS=(--visual s1docx/pdf/visual_status.json)
sc matrix.py coverage s1/rules.json s1/results.json -o s1/coverage_env.md --env s1/env.json "${VIS[@]}"
{ printf '# Rule Check Report\n\n'; cat s1/coverage_env.md; echo; cat s1/internal.md; } > s1/report_env.md
sc matrix.py verify s1/rules.json s1/report_env.md
grep -E "^(Visual pass|⏭️)" s1/report_env.md || true

echo; echo "### scenario 2: process model / regression"
sc extract.py "$P/process_v1.pdf" "$P/process_v2.pdf" "${EA[@]}" -o s2/ex
sc doc_diff.py "$P/process_v1.pdf" "$P/process_v2.pdf" -o s2/diff.json >/dev/null
sc doc_diff.py "$P/process_v1.docx" "$P/process_v2.docx" -o s2/diff_docx.json | sed -n 3p
M="$P/model_v1"
sc model_check.py check "$M/process_model.yaml" --rules "$M/rules.json" --mmd s2/v1.mmd
sc model_check.py invariants "$M/process_model.yaml" "$M/invariants.yaml" --doc s2/ex/process_v1.txt -o s2/inv_v1.json | tail -1
sc impact.py --model "$M/process_model.yaml" --diff s2/diff.json --rules "$M/rules.json" --invariants "$M/invariants.yaml" -o s2/impact >/dev/null
mkdir -p s2/.rule-check; cp -r "$S2/.rule-check/process" s2/.rule-check/process; cp "$S2/classification.json" s2/
sc model_check.py check s2/.rule-check/process/process_model.yaml --rules s2/.rule-check/process/rules.json | tail -1
sc model_check.py invariants s2/.rule-check/process/process_model.yaml s2/.rule-check/process/invariants.yaml --doc s2/ex/process_v2.txt -o s2/inv_v2.json | tail -1 || true
python3 "$REPO/tests/score_v2.py" s2
